//images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800&q=80"},{title:"Complete IT Security",description:"End-to-end protection for every device on your network, including enterprise-class malware/ransomware protection with automatic definition updates, regular OS patching, two-factor authentication, and password management.",image:"https://images.unsplash.com/photo-1563986768609-322da13575f3?w=800&q=80"},{title:"Device Care & Management",description:"Having your IT system managed by highly qualified technicians, rather than manual work by untrained staff, decreases the chances of physical damage to your systems.",image:"https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=800&q=80"}],includedTitle:"What's Included in Managed IT?",includedLead:"Pass the responsibility of network, server, device, and employee security and support from your team, to ours – allowing you to focus on what you do best – running your business.",included:[{title:"Network",description:"Cloud services are network dependent, which is why Keedco network management and monitoring services have become critical to IT."},{title:"Service Desk",description:"Keedco 24/7 support is about maximising service efficiency, resolving problems and driving continuous service improvement."},{title:"Infrastructure",description:"Keedco ensures your IT infrastructure is always optimised to support the stable and highly available services organisations demand."},{title:"Endpoint Management",description:"Client and server endpoints are managed as one estate, ensuring security and stability while maximising uptime and employee productivity."},{title:"Applications Management",description:"Keedco supports Software as well as on-premise deployments, ensuring applications are always optimised for the best possible user experience."},{title:"Managed Services Plus",description:"Keedco provides advanced management tools to clients who want to take their IT Service Management to a higher level."}]},"electrical-cctv":{badge:"KeedCo Electric",heroTitleLine1:"Electrical & CCTV for",heroTitleLine2:"every size of business",heroSubtitle:"Ensure all suspicious and criminal activity is identified and dealt with by professionals with our CCTV solutions.",heroBg:"https://images.unsplash.com/photo-1557597774-9d273605dfa9?w=1600&q=80",benefitsTitle:"Enjoy service that goes the extra mile",benefitsLead:"With our diverse range of CCTV services and packages, we can fully equip your business or premises with a bespoke CCTV solution that's designed to safeguard your site, assets and people.",benefits:[{title:"Tailormade CCTV Installation",description:"Our expert security technicians conduct a thorough site assessment and collaborate with you to develop a comprehensive and customized CCTV plan, ensuring optimal coverage regardless of site size or complexity.",image:"https://images.unsplash.com/photo-1557597774-9d273605dfa9?w=800&q=80"},{title:"Completely Bespoke Solutions",description:"We're one of few providers able to offer a totally tailormade CCTV solution for your site, regardless of size or industry.",image:"https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800&q=80"},{title:"An Affordable Solution",description:"Our CCTV packages are designed to be as budget-friendly as possible, and we'll work tirelessly to design a solution that works for your situation.",image:"https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=800&q=80"}],includedTitle:"What's Included in Electrical & CCTV?",included:[{title:"CCTV Installation",description:"Professional installation of CCTV cameras tailored to your site layout and security requirements."},{title:"Electrical Installation",description:"Full electrical installation services for commercial and residential premises."},{title:"Cable Management",description:"Neat, safe and compliant cable routing and management throughout your premises."},{title:"CCTV Repair & Maintenance",description:"Ongoing maintenance and rapid repair services to keep your CCTV system running at all times."},{title:"Digital Security Assessments",description:"Comprehensive assessments to identify vulnerabilities in your physical and digital security setup."},{title:"Access Control",description:"Installation and management of access control systems to restrict and monitor entry to your premises."}]},cybersecurity:{badge:"Cybersecurity",heroTitleLine1:"Protect your business",heroTitleLine2:"from cyberattacks",heroSubtitle:"Maintaining cybersecurity can be expensive – but it doesn't have to break the bank.",heroBg:"https://images.unsplash.com/photo-1510511459019-5dda7724fd87?w=1600&q=80",benefitsTitle:"Enhanced Suite of Cybersecurity Protection",benefitsLead:"Cybersecurity serves the dual purpose of safeguarding both your customers and yourself against any malicious activity that may cause damage or interruption.",benefits:[{title:"24/7 Monitoring & Defense",description:"We monitor network traffic for suspicious behaviour patterns throughout your organization. Using specialized tools, we can detect and prevent what hackers are attempting to do before they have the opportunity to do so.",image:"https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=800&q=80"},{title:"Enhanced Hardware",description:"We protect your business from unauthorized access to critical data assets and personnel by securing your company's network infrastructure.",image:"https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&q=80"},{title:"End-to-end Threat Protection",description:"We combine hardware and app-based solutions that include pentest-analysis and testing, password and access management, machine-learning AI, and monitoring.",image:"https://images.unsplash.com/photo-1614064641938-3bbee52942c7?w=800&q=80"}],includedTitle:"What's Included in Cyber Security?",included:[{title:"Network Security",description:"Protect your internal network from intrusions, unauthorized access, and data breaches."},{title:"DDoS Mitigation",description:"Defend against distributed denial-of-service attacks that can take your services offline."},{title:"Application Firewalls",description:"Filter and monitor HTTP traffic between your web applications and the internet."},{title:"Identity & Access Management",description:"Ensure only the right people have access to the right resources at the right times."},{title:"Endpoint Protection",description:"Secure every device on your network against malware, ransomware, and other threats."},{title:"Advanced Threat Protection",description:"AI-powered detection and response to sophisticated, targeted attacks on your business."}]},"backup-recovery":{badge:"Backup & Recovery",heroTitleLine1:"Recover your data",heroTitleLine2:"in case of loss.",heroSubtitle:"Get a secure, reliable and cost-effective backup service for any requirement & business size.",heroBg:"https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=1600&q=80",benefitsTitle:"Get back up and running should the worst happen",benefitsLead:"Loss of data and systems access can result in significant financial losses for your business. This is where our Disaster Recovery solution comes into play, providing you with the necessary insurance and assurance.",benefits:[{title:"Continuous, Reliable Data Protection",description:"We give you the peace of mind that your data is safe and secure and you'll have the assurance that normal business operation can be restored within minutes should a disaster happen.",image:"https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=800&q=80"},{title:"Minimise Downtime",description:"Manage your entire disaster recovery and continuity solutions from one single place, making things easier and quicker for you.",image:"https://images.unsplash.com/photo-1504868584819-f8e8b4b6d7e3?w=800&q=80"},{title:"Multiple Deployment Scenarios",description:"Deploy as an appliance, virtual appliance, or software to protect any physical, virtual, or cloud infrastructure running on Mac, Windows, or Linux.",image:"https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&q=80"}],includedTitle:"What's Included in Backup & Recovery?",included:[{title:"Reliable, Verified Backups",description:"Automated backups that are regularly tested and verified to ensure your data can always be restored."},{title:"Secure Cloud Storage",description:"Your backups are encrypted and stored in secure, geographically redundant cloud infrastructure."},{title:"Fast Restore Options",description:"Granular and full-system restore options that get your business back online in minutes, not days."}]},"it-consultancy":{badge:"IT Consultancy",heroTitleLine1:"IT Consultancy for",heroTitleLine2:"every size of business",heroSubtitle:"Helping you to make the right IT decisions and optimise your technology to deliver the operational outcomes you desire.",heroBg:"https://images.unsplash.com/photo-1542744173-8e7e53415bb0?w=1600&q=80",benefitsTitle:"Enjoy Enterprise IT consulting",benefitsLead:"We use our technical expertise to help your organisation become agile, reduce operational risk and enable your people to work smarter.",benefits:[{title:"Increased Operational Agility",description:"We support you to plan an IT environment that is agile, can rapidly adapt to changing operational needs, remove restrictions on growth, and better position you to meet evolving customer needs.",image:"https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&q=80"},{title:"Maximise your IT Investment",description:"It is not just about having the right technology in place, it is deploying and adopting it in the right way to truly generate a return on investment.",image:"https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&q=80"},{title:"Lay a Foundation for the Future",description:"We help you to make the right IT choices to establish a foundation from which you can continually evolve. An environment that is elastic, open and capable of taking you to where you want to go.",image:"https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800&q=80"},{title:"Knowledge & Skill Transfer",description:"We inject specific expertise to assist you on your journey but ensure that we take your people with us, sharing our thinking and skilling your people for their journey forward.",image:"https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=800&q=80"}],includedTitle:"What's Included in IT Consultancy?",included:[{title:"IT Audit & Health Check",description:"A thorough review of your current IT environment to identify risks, inefficiencies, and opportunities."},{title:"Network Vulnerability Audits",description:"Identify and address weaknesses in your network before they can be exploited."},{title:"Solution Scoping, Design & Procurement",description:"We help you define, design, and source the right technology solutions for your needs and budget."},{title:"Capacity Planning",description:"Ensure your IT infrastructure can scale to meet current and future business demands."},{title:"IT Roadmap",description:"A clear, prioritised plan for evolving your IT environment in line with your business strategy."},{title:"Requirements Analysis",description:"Detailed analysis of your business and technical requirements to inform the right IT decisions."}]},"custom-software":{badge:"Custom Software Development",heroTitleLine1:"Custom software for",heroTitleLine2:"your evolving needs",heroSubtitle:"Does your business rely on bespoke applications that have become hard to maintain, difficult to scale and complicated to deploy? We are here for you.",heroBg:"https://images.unsplash.com/photo-1461749280684-dccba630e2f6?w=1600&q=80",benefitsTitle:"Modernise your operations with bespoke software",benefitsLead:"Take advantage of modern cloud infrastructure to future-proof your investments in your applications. Modernising your applications can deliver greater agility and efficiency.",benefits:[{title:"Improved Deployments",description:"Reduce complexity and allow your IT teams to inc